{

        window.wikiClearAllCache = async function() {
            console.log('🧹 Starting comprehensive cache clear...');

            // 1. Clear localStorage
            const localStorageKeys = [];
            for (let i = 0; i < localStorage.length; i++) {
                const key = localStorage.key(i);
                if (key) localStorageKeys.push(key);
            }
            localStorageKeys.forEach(key => {
                localStorage.removeItem(key);
                console.log(`  ✓ Removed localStorage: ${key}`);
            });

            // 2. Clear sessionStorage
            const sessionStorageKeys = [];
            for (let i = 0; i < sessionStorage.length; i++) {
                const key = sessionStorage.key(i);
                if (key) sessionStorageKeys.push(key);
            }
            sessionStorageKeys.forEach(key => {
                sessionStorage.removeItem(key);
                console.log(`  ✓ Removed sessionStorage: ${key}`);
            });

            // 3. Clear all cookies
            document.cookie.split(";").forEach((c) => {
                const eqPos = c.indexOf("=");
                const name = eqPos > -1 ? c.substr(0, eqPos).trim() : c.trim();
                if (name) {
                    document.cookie = `${name}=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/`;
                    console.log(`  ✓ Removed cookie: ${name}`);
                }
            });

            // 4. Clear Service Worker cache
            if ('caches' in window) {
                try {
                    const cacheNames = await caches.keys();
                    for (const cacheName of cacheNames) {
                        await caches.delete(cacheName);
                        console.log(`  ✓ Deleted cache: ${cacheName}`);
                    }
                } catch (error) {
                    console.warn('  ⚠ Could not clear service worker cache:', error);
                }
            }

            // 5. Unregister Service Workers
            if ('serviceWorker' in navigator) {
                try {
                    const registrations = await navigator.serviceWorker.getRegistrations();
                    for (const reg of registrations) {
                        await reg.unregister();
                        console.log(`  ✓ Unregistered Service Worker: ${reg.scope}`);
                    }
                } catch (error) {
                    console.warn('  ⚠ Could not unregister Service Workers:', error);
                }
            }

            // 6. Clear backend cache via API
            try {
                const response = await __wikiEnv.fetch('/wiki/api/v1/admin/clear-tree-cache', {
                    method: 'POST'
                });
                const result = await response.json();
                console.log(`  ✓ Backend cache cleared: ${result.message}`);
            } catch (error) {
                console.warn('  ⚠ Could not clear backend cache:', error);
            }

            console.log('✅ Cache clearing complete! Reloading page...');
            // Force a hard reload to get fresh data
            __wikiEnv.location.href = __wikiEnv.location.href.split('?')[0] + '?clearCache=all&t=' + Date.now();
        };

        console.log('💡 Tip: Run window.wikiClearAllCache() in the console to clear everything');
    
}
